import { useEffect, useState } from 'react';
import PropTypes from 'prop-types';
import ReactApexChart from 'react-apexcharts';
import dayjs from 'dayjs';
// @mui
import { Card, CardHeader, Box, Grid, Typography } from '@mui/material';
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import { DemoContainer } from '@mui/x-date-pickers/internals/demo';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import CardContent from '@mui/material/CardContent';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import ChartDate from '../../../components/chart/ChartDate';
import ChartString from '../../../components/chart/ChartString';
import { axios } from '../../../utils/axios';
// components
import { useChart } from '../../../components/chart';
import useResponsive from '../../../hooks/useResponsive';
import { useMyContext } from '../../../pages/provider';


// ----------------------------------------------------------------------

AppWebsiteVisits.propTypes = {
  title: PropTypes.string,
  subheader: PropTypes.string,
  chartData: PropTypes.array.isRequired,
  chartLabels: PropTypes.arrayOf(PropTypes.string).isRequired,
};

export default function AppWebsiteVisits({ title, subheader, chartLabels, chartData, ...other }) {
  const [graph, setGraph] = useState('year');
  const { i18 } = useMyContext();
  const handleChangeGraph = (event) => {
    setGraph(event.target.value);
  };
  const chartOptions = useChart({
    plotOptions: { bar: { columnWidth: '16%' } },
    fill: { type: chartData.map((i) => i.fill) },
    labels: chartLabels,
    xaxis: { type: 'datetime' },
    tooltip: {
      shared: true,
      intersect: false,
      y: {
        formatter: (y) => {
          if (typeof y !== 'undefined') {
            return `${y.toFixed(0)} visits`;
          }
          return y;
        },
      },
    },
  });
  const [selectedDate, setSelectedDate] = useState(dayjs(new Date()));
  const [stats, setStats] = useState([]);
  const [xlabel, setXlabel] = useState([]);
  const [checkoutYlabel, setCheckoutYlabel] = useState([]);
  const [bookYlabel, setBookYlabel] = useState([]);
  const handleDateChange = (date) => {
    setSelectedDate(date);
  };
  const BookingStats = async () => {
    const res = await axios.get(`/module/admin/dashboard/bookingStat?date=${selectedDate}&status=${graph}`);
    if (res.status === 200) {
      const obj = {};
      const userProvidedDate = new Date(selectedDate);
      if (graph === 'month') {
        res.data.data.bookingStat.forEach((item) => {
          obj[item.date] = item;
        });
        const xlabel = getAllDatesInMonth(userProvidedDate);
        const xlabelStrings = xlabel.map((item) => item.name);
        setXlabel(xlabelStrings);

        const checkoutlabels = xlabel.map((item) => {
          if (obj[item.key] && obj[item.key].value && obj[item.key].value[0]?.checkoutCount) {
            return obj[item.key].value[0]?.checkoutCount;
          }
          return 0;
        });
        setCheckoutYlabel(checkoutlabels);
        const bookinglabels = xlabel.map((item) => {
          if (obj[item.key]) {
            return obj[item.key].bookingCount;
          }
          return 0;

        });
        setBookYlabel(bookinglabels);
      } else if (graph === 'week') {
        res.data.data.bookingStat.forEach((item) => {
          const day = new Date(item.date).getDay();
          obj[day + 1] = item;
        });
        const xlabelWeek = getDaysOfWeekArrayWithKeys();
        const xlabelStrings = xlabelWeek.map((data) => data.name);
        setXlabel(xlabelStrings);

        const checkoutlabels = xlabelWeek.map((data) => {
          if (obj[data.key] && obj[data.key].value && obj[data.key].value[0]?.checkoutCount) {
            return obj[data.key].value[0]?.checkoutCount;
          }
          return 0;
        });
        setCheckoutYlabel(checkoutlabels);
        const bookinglabels = xlabelWeek.map((data) => {
          if (obj[data.key]) {
            return obj[data.key].bookingCount;
          }
          return 0;
        });
        setBookYlabel(bookinglabels);
      } else if (graph === 'year') {
        res.data.data.bookingStat.forEach((item) => {
          obj[item._id] = item;
        });
        const xlabelWeek = getMonthsArrayWithKeys();
        const xlabelStrings = xlabelWeek.map((data) => data.name);
        setXlabel(xlabelStrings);

        const checkoutlabels = xlabelWeek.map((data) => {
          if (obj[data.key] && obj[data.key].value && obj[data.key].value[0]?.checkoutCount) {
            return obj[data.key].value[0]?.checkoutCount;
          }
          return 0;
        });
        setCheckoutYlabel(checkoutlabels);
        const bookinglabels = xlabelWeek.map((data) => {
          if (obj[data.key]) {
            return obj[data.key].bookingCount;
          }
          return 0;
        });
        setBookYlabel(bookinglabels);
      }

      setStats(obj);
    }
  };
  const userProvidedDate = new Date(selectedDate); // Replace with the user-provided date
  const allDatesInMonth = getAllDatesInMonth(userProvidedDate);
  const month = getMonthsArrayWithKeys();
  const week = getDaysOfWeekArrayWithKeys();
  useEffect(() => {
    BookingStats();
  }, [graph, selectedDate]);

  const mdDown = useResponsive('down', 'md')
  return (
    <Grid container spacing={2} sx={{ marginTop: '30px' }}>
      <Grid item xs={12} md={8}>
        <Card>
          <CardHeader title={title} subheader={subheader} />
          <Box sx={{ p: 3, pb: 1 }} dir="ltr">
            <div
              style={{
                display: 'flex',
                flexDirection: mdDown ? 'column' : 'row',
                justifyContent: mdDown ? 'center' : 'end',
                gap: '30px',
                alignItems: 'center',
                marginBottom: '40px',
              }}
            >
              <LocalizationProvider dateAdapter={AdapterDayjs}>
                <DemoContainer components={['DatePicker']} sx={{ width: mdDown ? '100%' : '40%', paddingTop: '0px' }}>
                  <DatePicker value={selectedDate} onChange={handleDateChange} />
                </DemoContainer>
              </LocalizationProvider>
              <FormControl sx={{ width: mdDown ? '100%' : '40%', marginBottom: '0px' }}>
                <Select
                  value={graph}
                  onChange={handleChangeGraph}
                  displayEmpty
                  inputProps={{ 'aria-label': 'Without label' }}
                >
                  <MenuItem value="week">week</MenuItem>
                  <MenuItem value="month">month</MenuItem>
                  <MenuItem value="year">year</MenuItem>
                </Select>
              </FormControl>
            </div>
            {graph === 'month' ? (
              <ChartDate
                chartLabels={xlabel}
                type={graph}
                chartData={[
                  {
                    name: 'Booked Count',
                    type: 'line',
                    fill: 'solid',
                    data: bookYlabel,
                  },
                  {
                    name: 'Checkout Count',
                    type: 'line',
                    fill: 'solid',
                    data: checkoutYlabel,
                  },
                ]}
              />
            ) : (
              <ChartString
                chartLabels={xlabel}
                type={graph}
                chartData={[
                  {
                    name: 'Booked Count',
                    type: 'line',
                    fill: 'solid',
                    data: bookYlabel,
                  },
                  {
                    name: 'Checkout Count',
                    type: 'line',
                    fill: 'solid',
                    data: checkoutYlabel,
                  },
                ]}
              />
            )}
          </Box>
        </Card>
      </Grid>
      <Grid item xs={12} md={4}>
        <Card style={{ maxHeight: '580px', overflow: 'auto' }}>
          <CardContent>
            <Typography sx={{ fontSize: 20, marginBottom: '10px', fontWeight: 'bold' }} gutterBottom>
              {i18?.DASHBOARD?.TRIPS_STATISTICS || "Trips Statistics"}
              <p style={{ fontSize: '12px', color: "#717171" }}>{i18?.DASHBOARD?.CHECKOUT_BOOKED || "CHECKOUT/BOOKED"}</p>
            </Typography>
            {graph === 'week' && (
              <div>
                {week.map((data) =>
                (
                  <div key={data} style={{ padding: '15px', display: 'flex', justifyContent: 'space-between' }}>
                    <p>{data.name}</p>
                    <p>
                      {stats[data.key]
                        ? `${stats[data.key].value[0]?.checkoutCount || 0}  / ${stats[data.key].bookingCount} `
                        : '0 / 0'}
                    </p>
                  </div>
                )
                )}
              </div>
            )}
            {graph === 'year' && (
              <div>
                {month.map((data) =>
                (
                  <div key={data} style={{ padding: '15px', display: 'flex', justifyContent: 'space-between' }}>
                    <p>{data.name}</p>
                    <p>
                      {stats[data.key]
                        ? `${stats[data.key].value[0]?.checkoutCount || 0}  / ${stats[data.key].bookingCount || 0}`
                        : '0 / 0'}
                    </p>
                  </div>
                )
                )}
              </div>
            )}
            {graph === 'month' && (
              <>
                {allDatesInMonth.map((item, index) => (
                  <div key={index}>
                    <div style={{ padding: '15px', display: 'flex', justifyContent: 'space-between' }}>
                      <p>{item.name}</p>
                      <p>
                        {stats[item.key]
                          ? `${stats[item.key].value[0]?.checkoutCount || 0} / ${stats[item.key].bookingCount || 0} `
                          : '0 / 0'}
                      </p>
                    </div>
                  </div>
                ))}
              </>
            )}
          </CardContent>
        </Card>
      </Grid>
    </Grid>
  );
}
function formatDateToYYYYMMDD(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0'); // Months are zero-based
  const day = String(date.getDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}
function getAllDatesInMonth(userProvidedDate) {
  const startDate = new Date(userProvidedDate.getFullYear(), userProvidedDate.getMonth(), 1);
  const endDate = new Date(userProvidedDate.getFullYear(), userProvidedDate.getMonth() + 1, 0);

  const datesArray = [];

  for (let date = startDate; date <= endDate; date.setDate(date.getDate() + 1)) {
    const dateKey = formatDateToYYYYMMDD(date);
    const name = `${date.getDate()} ${getMonthName(date.getMonth())}`;
    datesArray.push({
      key: dateKey,
      name,
    });
  }

  return datesArray;
}

function getMonthName(monthIndex) {
  const monthNames = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
  ];

  return monthNames[monthIndex];
}

function getMonthsArrayWithKeys() {
  const monthNames = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
  ];

  return monthNames.map((month, index) => ({
    key: index + 1,
    name: month,
  }));
}
function getDaysOfWeekArrayWithKeys() {
  const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

  return dayNames.map((day, index) => ({
    key: index + 1,
    name: day,
  }));
}
