import { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
// @mui
import { Grid, Typography } from '@mui/material';
import Card from '@mui/material/Card';

import CircularProgress from '@mui/material/CircularProgress';
import Box from '@mui/material/Box';
import CardContent from '@mui/material/CardContent';
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
import Rating from '@mui/material/Rating';
import StarIcon from '@mui/icons-material/Star';
import Select from '@mui/material/Select';
import { amber, red } from '@mui/material/colors';
import { useNavigate } from 'react-router-dom';
import Alert from '@mui/material/Alert';
import { axios } from '../../utils/axios';
import { IMAGE_URL } from '../../utils/config';
// sections
import { AppWebsiteVisits, AppWidgetSummary } from '../../sections/@dashboard/app';
import { useMyContext } from '../provider';
import { replaceStarsInEmailAddress, replaceStarsInMobileNumber, capitalizeFirstLetter } from '../../utils/sensitive';

// ----------------------------------------------------------------------

export default function DashboardAppPage() {
  const navigate = useNavigate();
  const [data, setData] = useState({})
  const [progress, setProgress] = useState('');
  const [day, setDay] = useState('daily');
  const [ratings, setRatings] = useState([])
  const [recentUser, setRecentUser] = useState([])
  const [recentHost, setRecentHost] = useState([])
  const [earnings, setEarnings] = useState([])
  const [importantSettings, setImportantSettings] = useState([]);
  const { i18 } = useMyContext()
  const fetchData = async () => {
    const res = await axios.get('module/admin/dashboard/totalCount')
    if (res.status === 200) {
      setData(res.data.data.totalCount)
      const calculatedPercentage = (res.data.data.totalCount.activeUser / res.data.data.totalCount.totalUser) * 100;
      setProgress(Math.round(calculatedPercentage))
    }
  }
  useEffect(() => {
    fetchData()
    EarningReport()
    Ratings()
    RecentUser()
    RecentHost()
    fetchImportantSettings();
  }, [day])

  const handleChange = (event) => {
    setDay(event.target.value);
  };

  const fetchImportantSettings = async () => {
    const response = await axios.get(`module/settings/fieldStatus`)
    if (response?.status === 200) setImportantSettings(response?.data?.data)
  }

  const EarningReport = async () => {
    const res = await axios.get(`/module/admin/dashboard/earningReport?filterType=${day}`)
    if (res.status === 200) {
      setEarnings(res.data.data.report)
    }
  }
  const Ratings = async () => {
    const res = await axios.get('/module/admin/dashboard/ratingReport')
    if (res.status === 200) {
      setRatings(res.data.data.rate)
    }
  }
  const RecentUser = async () => {
    const res = await axios.get('/module/admin/dashboard/recentUsers')
    if (res.status === 200) {
      setRecentUser(res.data.data.recentUser)
    }
  }
  const RecentHost = async () => {
    const res = await axios.get('/module/admin/dashboard/recentProviders')
    if (res.status === 200) {
      setRecentHost(res.data.data.recentUser)
    }
  }

  // const heading = {
  //   "app": {
  //     "port": false,
  //     "appName": false,
  //     "desc": false,
  //     "appMode": false,
  //     "logo": false,
  //     "favicon": false,
  //     "baseurl": false
  //   },
  //   "site": {
  //     "sensitiveDatas": false,
  //     "titleName": false,
  //     "language": false,
  //     "currency": false,
  //     "currencySymbol": false,
  //     "phoneCode": false,
  //     "countryCode": false,
  //     "mapCoordinates": {
  //       "lat": false,
  //       "lng": false
  //     }
  //   },
  //   "chat": {
  //     "chatPropertyId": false,
  //     "chatWidgetId": false
  //   },
  //   "socialLinks": {
  //     "facebook": false,
  //     "twitter": false,
  //     "instagram": false
  //   },
  //   "google": {
  //     "googleClientId": false,
  //     "googleClientSecret": false,
  //     "mapApiKey": false,
  //     "googleRedirectUrl": false,
  //     "googleRecaptchaSiteKey": false,
  //     "googleRecaptchaSecretKey": false
  //   },
  //   "emailGateway": {
  //     "AppName": false,
  //     "name": false,
  //     "smtpConfig": {
  //       "host": false,
  //       "port": false,
  //       "auth": {
  //         "user": false,
  //         "pass": false
  //       }
  //     }
  //   },
  //   "paymentGateway": {
  //     "name": false,
  //     "mode": false,
  //     "keySecret": false,
  //     "publishableKey": false,
  //     "kkSecret": false
  //   },
  // };
  
  const handleCardClick = (category, settings) => {
    
    const disabledSettings = Object.entries(settings)
      .filter(([_, isEnabled]) => !isEnabled) // Extract keys with `false` value
      .map(([settingName]) => settingName) // Get the names of the settings
      .join(","); // Join them as a comma-separated string

    if (["chat", "app", "google", "site", "socialLinks"].includes(category)) {
      navigate("/dashboard/apps-settings", { state: { categorys: category, highlight: disabledSettings } });
    } else if (category === "emailGateway") {
      navigate("/dashboard/mailgateway-settings", { state: { highlight: disabledSettings } });
    } else if (category === "paymentGateway") {
      navigate("/dashboard/payment-settings", { state: { highlight: disabledSettings } });
    }
  };
  


  // Function to recursively check if any value in the object is false
  const hasFalseValue = (obj) => {
    if (typeof obj !== 'object' || obj === null) {
      return obj === false;
    }

    return Object.values(obj).some(value => hasFalseValue(value));
  };

  const validCategories = ['chat', 'app', 'google', 'site', 'socialLinks', 'emailGateway', 'paymentGateway'];

  // Filter out headings that match the valid categories and contain any false values
  const filteredHeadings = Object.entries(importantSettings)
    .filter(([category, settings]) =>
      validCategories.includes(category) && hasFalseValue(settings)
    );

  const formatToTitleCase = (text) => 
     text
      .replace(/([a-z])([A-Z])/g, '$1 $2') // Add space before capital letters
      .replace(/_/g, ' ') // Replace underscores with spaces if necessary
      .replace(/\b\w/g, (char) => char.toUpperCase()) // Capitalize the first letter of each word
  ;

  return (
    <>
      <Helmet>
        <title> Dashboard | Admin Panel </title>
      </Helmet>

      <>
        <Card sx={{ backgroundColor: "", margin: "0px", padding: "20px", alignSelf: "center" }}>
          <Typography variant="h4" sx={{ mb: 5 }}>
            {i18?.DASHBOARD?.HI_WELCOME_BACK || "Hi Welcome back"}
          </Typography>

          <Grid container spacing={4}>
            <Grid item xs={12} sm={6} md={3}>
              <AppWidgetSummary title={i18?.DASHBOARD?.USER || "User"} total={data.totalUser} icon={'zondicons:user'} />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <AppWidgetSummary title={i18?.DASHBOARD?.PROVIDER || "Provider"} total={data.totalProvider} color="info" icon={'fluent:person-settings-16-filled'} iconWidth='30px' iconHeight='30px' />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <AppWidgetSummary title={i18?.DASHBOARD?.CATEGORY || "Category"} total={data.totalCategories} color="warning" icon={'tabler:category-filled'} iconWidth='26px' iconHeight='26px' />
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <AppWidgetSummary title={i18?.DASHBOARD?.LISTINGS || "Listings"} total={data.totalListings} color="error" icon={'gg:list'} iconWidth='30px' iconHeight='30px' />
            </Grid>
          </Grid>
        </Card>

        {filteredHeadings?.length > 0 && <Card sx={{ p: 3, mt: 4 }}>
          <Typography variant="h5" sx={{ mb: 3 }}>
            {i18?.DASHBOARD?.IMPORTANT_SETTINGS || "Important Settings"}
          </Typography>
          <Grid container spacing={2}>
            {filteredHeadings.map(([category, settings], index) => (
              <Grid item xs={12} md={6} key={index}>
                <Alert
                  sx={{
                    '& .MuiAlert-icon': {
                      mt: '6px'
                    },
                    cursor: 'pointer'
                  }}
                  severity={(category === 'google' || category === 'paymentGateway' || category === 'emailGateway') ? "error" : "warning"}
                  onClick={() => handleCardClick(category, settings)}
                >
                  <Typography variant="h6">
                    {formatToTitleCase(category)}
                  </Typography>
                  <Typography variant="body1">
                    {Object.entries(settings)
                      .filter(([_, isEnabled]) => !isEnabled) // Show only false values
                      .map(([settingName]) => formatToTitleCase(settingName)) // Format setting names
                      .join(', ')} {/* Join false settings as comma-separated */}
                  </Typography>
                </Alert>
              </Grid>
            ))}

          </Grid>
        </Card>}

        <Grid container spacing={4} sx={{ width: "100%", margin: "0" }}>
          <AppWebsiteVisits
            title={i18?.DASHBOARD?.TRIPS_STATISTICS || "Trips Statistics"}
            subheader={i18?.DASHBOARD?.CHECKOUT_BOOKED || "CHECKOUT/BOOKED"}
            chartLabels={[]}
            chartData={[{},]}
          />


          <Grid xs={12} md={6} lg={4} sx={{ marginTop: '30px' }}>
            <Card>
              <CardContent>
                <Typography sx={{ fontSize: 20, marginBottom: '10px', fontWeight: 'bold' }} gutterBottom>
                  {i18?.DASHBOARD?.USER_COUNTS || "User Counts"}
                </Typography>
                <Grid container >
                  <Box sx={{ position: 'relative', display: 'inline-flex' }}>
                    <CircularProgress variant="determinate" value={progress} size={100} sx={{ color: '#ff385c' }} />
                    <Box
                      sx={{
                        top: 0,
                        left: 0,
                        bottom: 0,
                        right: 0,
                        position: 'absolute',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                      }}
                    >
                      <Typography variant="caption" component="div" color="text.secondary">
                        {progress}%
                      </Typography>
                    </Box>
                  </Box>
                  <h3 style={{ margin: 'auto' }}>
                    {data.activeUser} {i18?.DASHBOARD?.ACTIVE || "Active"}
                    <p style={{ fontSize: '15px', color: '#717171', marginBottom: '0px' }}>
                      {i18?.DASHBOARD?.OUT_OF || "Out Of"} {data.totalUser}
                    </p>
                  </h3>

                </Grid>
              </CardContent>
            </Card>
            <Grid item sx={{ marginTop: '30px' }}>
              <Card>
                <CardContent>
                  <Grid >
                    <Typography sx={{ fontSize: 20, marginBottom: '10px', fontWeight: 'bold' }} gutterBottom>
                      {i18?.DASHBOARD?.TRIP_EARNING_REPORT || "Rental earning "}
                    </Typography>

                    <FormControl fullWidth >
                      <Select
                        value={day}
                        onChange={handleChange}
                        displayEmpty
                        inputProps={{ 'aria-label': 'Without label' }}>
                        <MenuItem value='daily'>{i18?.DASHBOARD?.DAILY || "Daily"}</MenuItem>
                        <MenuItem value='weekly'>{i18?.DASHBOARD?.WEEKLY || "Weekly"}</MenuItem>
                        <MenuItem value='monthly'>{i18?.DASHBOARD?.MONTHLY || "Monthly"}</MenuItem>
                      </Select>

                    </FormControl>
                  </Grid>
                  {earnings ?
                    <div style={{ marginTop: '20px' }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between', padding: '10px' }}>
                        <div >
                          <h5><b>{i18?.DASHBOARD?.BOOKINGS || "Bookings"}</b></h5>
                        </div>

                        <div>
                          <p style={{ marginBottom: '0px', fontSize: '18px' }}>{earnings.totalBookings}</p>
                        </div>
                      </div>

                      <div style={{ display: 'flex', justifyContent: 'space-between', padding: '10px' }}>
                        <div >
                          <h5><b>{i18?.DASHBOARD?.BOOKING_PAYMENT || "Booking Payment"}</b></h5>
                        </div>

                        <div>
                          <p style={{ marginBottom: '0px', fontSize: '18px' }}>{earnings.totalBookingPayment}</p>
                        </div>
                      </div>

                      <div style={{ display: 'flex', justifyContent: 'space-between', padding: '10px' }}>
                        <div >
                          <h5><b>{i18?.DASHBOARD?.BOOKING_COMMISSION || "Booking Commission"}</b></h5>
                        </div>

                        <div>
                          <p style={{ marginBottom: '0px', fontSize: '18px' }}>{earnings.totalBookingCommision}</p>
                        </div>
                      </div>

                      <div style={{ display: 'flex', justifyContent: 'space-between', padding: '10px' }}>
                        <div >
                          <h5><b>{i18?.DASHBOARD?.HOST_AMOUNT || "Host Amount"}</b></h5>
                        </div>

                        <div>
                          <p style={{ marginBottom: '0px', fontSize: '18px' }}>{earnings.totalHostAmount}</p>
                        </div>
                      </div>
                    </div>

                    :

                    <Typography sx={{ fontSize: 20, marginBottom: '10px', fontWeight: 'bold', display: "flex", justifyContent: 'center', alignItems: 'center', marginTop: '30px' }} gutterBottom>
                      {i18?.DASHBOARD?.NO_DATA_FOUND || "No Data Found"}
                    </Typography>
                  }

                </CardContent>
              </Card>
            </Grid>
          </Grid>
          <Grid item xs={12} md={6} lg={4}>
            <Card
              style={{
                // boxShadow: ' 5px 5px 10px 5px rgba(0, 0, 0, 0.2)', 
                maxHeight: '500px', overflow: 'auto'
              }}>
              <CardContent>
                <Typography sx={{ fontSize: 20, marginBottom: '10px', fontWeight: 'bold' }} gutterBottom>
                  {i18?.DASHBOARD?.RECENTS_USERS || "Recent users"}
                </Typography>
                {recentUser.map((data) =>
                (
                  <div key={data}>
                    <div style={{ padding: '10px', display: 'flex', gap: '20px' }}>
                      <img src={data?.profileImage ? `${IMAGE_URL}${data.profileImage}` : `${process.env.PUBLIC_URL}/assets/icons/proImage.png`} alt='img' style={{ width: '70px', height: '60px', borderRadius: '10px' }} />
                      <div style={{ display: 'grid' }}>
                        {data.email &&
                          <p style={{ marginBottom: '0px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{data?.email ? replaceStarsInEmailAddress(data?.email, '1', data?.email) : ""}</p>
                        }

                        {data.firstname &&
                          <p style={{ marginBottom: '0px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{capitalizeFirstLetter(data?.firstname)}</p>
                        }

                        {data.phone &&
                          <p style={{ marginBottom: '0px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{data?.phone ? replaceStarsInMobileNumber(data?.phone, "1", data?.phone) : ""}</p>
                        }
                      </div>
                    </div>
                  </div>
                )
                )}
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={6} lg={4}>
            <Card
              style={{ maxHeight: '500px', overflow: 'auto' }}>
              <CardContent>
                <Typography sx={{ fontSize: 20, marginBottom: '10px', fontWeight: 'bold' }} gutterBottom>
                  {i18?.DASHBOARD?.RATINGS || "Ratings"}
                </Typography>
                {ratings.map((data) =>
                (
                  <div key={data}>
                    <div style={{ padding: '10px', display: 'flex', gap: '20px' }}>
                      <img src={data.attachmentData ? `${IMAGE_URL}${data.attachmentData.image.coverImage}` : `${process.env.PUBLIC_URL}/assets/icons/proImage.png`} alt='img' style={{ width: '80px', height: '60px', borderRadius: '10px', objectFit: 'cover' }} />
                      <div style={{ display: 'grid' }}>
                        <p style={{ fontWeight: 'bold', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: '200px', marginBottom: '0px' }}>{data.propertyName}</p>
                        <Box
                          sx={{
                            width: 200,
                            display: 'flex',
                            alignItems: 'center',
                          }}
                        >
                          <Rating
                            name="text-feedback"
                            value={data.totalRatingCount}
                            readOnly
                            precision={0.5}
                            sx={{
                              "& .MuiRating-iconFilled": {
                                color: "#ff385c",
                              },
                              "& .MuiRating-iconFocus": {
                                color: "orange",
                              },
                              "& .MuiRating-iconHover": {
                                color: "green",
                              },
                            }}
                            emptyIcon={<StarIcon sx={{ opacity: 0.55 }} fontSize="inherit" />}
                          />
                        </Box>
                      </div>
                    </div>
                  </div>
                )
                )}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </>
    </>
  );
}
